const navItems=document.querySelectorAll('.nav-item'),pages=document.querySelectorAll('.page'),title=document.getElementById('pageTitle'),sidebar=document.getElementById('sidebar');

const VERSUS_KEY='unbeerable_versus_duel_v1';
const VERSUS_WEEKS=4;
function defaultVersus(){const names=["HECT","edeN","FML","IMI","WYZ","MKT","AdHD","8EER","pc6","UPt","xBoM","DxL","7IB","B52","tMp","KTI"];return{teams:names.map(name=>({name,power:'',nationality:''})),results:{}}}
function loadVersus(){try{const x=JSON.parse(localStorage.getItem(VERSUS_KEY)||'null');if(x&&x.teams?.length===16)return x}catch{}return defaultVersus()}
let versusData=loadVersus();
(function migrateVersusPlaceholders(){
  const names=['HECT','edeN','FML','IMI','WYZ','MKT','AdHD','8EER','pc6','UPt','xBoM','DxL','7IB','B52','tMp','KTI'];
  const untouched=versusData.teams?.length===16&&versusData.teams.every((t,i)=>t.name==='Alliance '+(i+1))&&Object.keys(versusData.results||{}).length===0;
  if(untouched){
    versusData.teams=names.map((name,i)=>({name,power:versusData.teams[i]?.power||'',nationality:versusData.teams[i]?.nationality||''}));
    localStorage.setItem(VERSUS_KEY,JSON.stringify(versusData));
  }
})();
let versusSaveTimer=null,versusCloudLoaded=false;
function saveVersus(){localStorage.setItem(VERSUS_KEY,JSON.stringify(versusData));if(cloudReady&&versusCloudLoaded){clearTimeout(versusSaveTimer);versusSaveTimer=setTimeout(saveVersusCloud,350)}}
async function saveVersusCloud(showStatus=false){const status=document.getElementById('versusSaveStatus');if(!cloudReady){if(showStatus&&status)status.textContent='Cloud not connected';return false}try{if(showStatus&&status)status.textContent='Saving…';await api('/rest/v1/versus_active_tournament?on_conflict=slot',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({slot:'current',tournament_data:versusData,updated_at:new Date().toISOString()})});if(status)status.textContent='Saved to cloud';return true}catch(e){console.warn('Versus autosave failed',e);if(status)status.textContent='Save failed';if(showStatus)alert('Could not save Versus data: '+e.message);return false}}
async function loadActiveVersus(){if(!cloudReady)return;try{const rows=await api('/rest/v1/versus_active_tournament?slot=eq.current&select=tournament_data,updated_at');if(rows?.length&&rows[0].tournament_data?.teams?.length===16){versusData=rows[0].tournament_data;localStorage.setItem(VERSUS_KEY,JSON.stringify(versusData));renderVersus()}else{await api('/rest/v1/versus_active_tournament',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({slot:'current',tournament_data:versusData})})}versusCloudLoaded=true}catch(e){console.warn('Versus active load failed',e);versusCloudLoaded=true}}
function resultFor(teamIndex,week){for(const [key,r] of Object.entries(versusData.results)){const [w,m]=key.split('-').map(Number);if(w!==week)continue;const p=versusPairings(week)[m];if(!p)continue;if(p.a===teamIndex)return r;if(p.b===teamIndex)return r==='W'?'L':r==='L'?'W':''}return''}
function pathBefore(teamIndex,week){let p='';for(let w=1;w<week;w++)p+=resultFor(teamIndex,w);return p}
function fullPath(teamIndex){let p='';for(let w=1;w<=VERSUS_WEEKS;w++){const r=resultFor(teamIndex,w);if(!r)break;p+=r}return p}
function pathStrength(path){let n=0;for(const c of path)n=n*2+(c==='W'?1:0);return n}
function versusPairings(week){
 if(week===1)return Array.from({length:8},(_,i)=>({a:i*2,b:i*2+1,path:''}));
 const groups={};for(let i=0;i<16;i++){const p=pathBefore(i,week);if(p.length!==week-1)continue;(groups[p]??=[]).push(i)}
 return Object.keys(groups).sort((a,b)=>pathStrength(b)-pathStrength(a)||a.localeCompare(b)).flatMap(path=>{
   const g=groups[path],out=[];for(let i=0;i+1<g.length;i+=2)out.push({a:g[i],b:g[i+1],path});return out
 })
}
function versusRecord(i){const p=fullPath(i);return{w:[...p].filter(x=>x==='W').length,l:[...p].filter(x=>x==='L').length,path:p}}
function renderDashboardVersus(){
 const el=document.getElementById('dashboardVersusOpponent'),badge=document.getElementById('dashboardVersusWeek');if(!el||!badge)return;
 const idx=versusData.teams.findIndex(t=>(t.name||'').trim().toUpperCase()==='8EER');
 if(idx<0){badge.textContent='Week —';el.innerHTML='<div class="train-empty">8EER is not in the active Versus tournament.</div>';return}
 let week=1;
 for(let w=1;w<=VERSUS_WEEKS;w++){if(!resultFor(idx,w)){week=w;break}week=Math.min(w+1,VERSUS_WEEKS)}
 const pair=versusPairings(week).find(p=>p.a===idx||p.b===idx);
 badge.textContent='Week '+week;
 if(!pair){el.innerHTML='<div class="train-empty">Complete the previous week to generate 8EER’s next opponent.</div>';return}
 const oi=pair.a===idx?pair.b:pair.a,me=versusData.teams[idx],opp=versusData.teams[oi],rec=versusRecord(idx),orec=versusRecord(oi),done=!!resultFor(idx,week);
 el.innerHTML='<div class="versus-dashboard-match"><div class="versus-dashboard-team home"><small>YOUR ALLIANCE</small><strong>8EER</strong><span>'+esc(me.power||'Power —')+'</span><div class="versus-dashboard-record">'+rec.w+'-'+rec.l+' <b>'+esc(rec.path||'Opening')+'</b></div></div><div class="versus-dashboard-vs"><span>VS</span><small>'+(done?'Week complete':'Current matchup')+'</small></div><div class="versus-dashboard-team"><small>OPPONENT</small><strong>'+esc(opp.name||('Alliance '+(oi+1)))+'</strong><span>'+esc(opp.power||'Power —')+'</span><div class="versus-dashboard-record">'+orec.w+'-'+orec.l+' <b>'+esc(orec.path||'Opening')+'</b></div><em>'+esc(opp.nationality||'Region —')+'</em></div></div>'
}
function parseVersusPower(v){
 const raw=String(v||'').trim().toUpperCase().replace(/\s/g,'');if(!raw)return 0;
 const m=raw.match(/^([+-]?[0-9]+(?:[.,][0-9]+)?)([KMBT])?$/);
 if(m){let n=Number(m[1].replace(',','.'));if(!Number.isFinite(n))return 0;const mult={K:1e3,M:1e6,B:1e9,T:1e12};return n*(mult[m[2]]||1)}
 const n=Number(raw.replace(/,/g,'').replace(/[^0-9.+-]/g,''));return Number.isFinite(n)?n:0
}
function compactVersusPower(n){return n>=1e12?(n/1e12).toFixed(2)+'T':n>=1e9?(n/1e9).toFixed(2)+'B':n>=1e6?(n/1e6).toFixed(2)+'M':n>=1e3?(n/1e3).toFixed(1)+'K':String(Math.round(n))}
function renderVersusPrediction(){
 const root=document.getElementById('versusPrediction'),badge=document.getElementById('versusPredictionWeek');if(!root||!badge)return;
 const idx=versusData.teams.findIndex(t=>(t.name||'').trim().toUpperCase()==='8EER');if(idx<0){badge.textContent='Week —';root.innerHTML='<div class="train-empty">8EER is not in the active tournament.</div>';return}
 let week=1;for(let w=1;w<=VERSUS_WEEKS;w++){if(!resultFor(idx,w)){week=w;break}week=Math.min(w+1,VERSUS_WEEKS)}
 const pair=versusPairings(week).find(p=>p.a===idx||p.b===idx);badge.textContent='Week '+week;if(!pair){root.innerHTML='<div class="train-empty">Complete the previous week to generate 8EER’s next opponent.</div>';return}
 const oi=pair.a===idx?pair.b:pair.a,me=versusData.teams[idx],opp=versusData.teams[oi],mp=parseVersusPower(me.power),op=parseVersusPower(opp.power);
 if(!mp||!op){root.innerHTML='<div class="train-empty">Enter Power for both 8EER and '+esc(opp.name)+' to calculate the prediction.</div>';return}
 const favorite=mp===op?'Even matchup':mp>op?'8EER':opp.name,diff=Math.abs(mp-op),pct=Math.max(mp,op)?diff/Math.max(mp,op)*100:0,total=mp+op,ms=mp/total*100,os=op/total*100;
 root.innerHTML='<div class="versus-prediction-head"><div><small>8EER</small><strong>'+compactVersusPower(mp)+'</strong></div><div class="versus-prediction-call"><span>POWER-BASED FAVORITE</span><strong>'+esc(favorite)+'</strong><small>'+(favorite==='Even matchup'?'Equal entered power':compactVersusPower(diff)+' advantage · '+pct.toFixed(1)+'% stronger by entered power')+'</small></div><div><small>'+esc(opp.name)+'</small><strong>'+compactVersusPower(op)+'</strong></div></div><div class="versus-power-bar"><span style="width:'+ms.toFixed(2)+'%"></span><i style="width:'+os.toFixed(2)+'%"></i></div><div class="versus-power-shares"><span>8EER '+ms.toFixed(1)+'%</span><span>'+esc(opp.name)+' '+os.toFixed(1)+'%</span></div><p class="muted small">Prediction uses entered total alliance power only. Participation, saved resources, activity, and strategy can change the actual result.</p>'
}
function renderVersus(){
 const list=document.getElementById('versusTeamList'),weeks=document.getElementById('versusWeeks'),stand=document.getElementById('versusStandingsBody');if(!list||!weeks||!stand)return;
 list.innerHTML=versusData.teams.map((t,i)=>'<div class="versus-team-row"><span class="versus-seed">#'+(i+1)+'</span><input data-vteam="'+i+'" data-field="name" value="'+esc(t.name)+'" placeholder="Alliance name"><input data-vteam="'+i+'" data-field="power" value="'+esc(t.power)+'" placeholder="Power"><select data-vteam="'+i+'" data-field="nationality"><option value="">Nationality</option>'+['Europe','America','Asia','Middle East'].map(n=>'<option value="'+n+'" '+(t.nationality===n?'selected':'')+'>'+n+'</option>').join('')+'</select></div>').join('');
 list.querySelectorAll('input,select').forEach(inp=>inp.onchange=()=>{const i=Number(inp.dataset.vteam),field=inp.dataset.field;versusData.teams[i][field]=inp.value.trim();saveVersus();renderVersus()});
 weeks.innerHTML=Array.from({length:4},(_,wi)=>{const week=wi+1,pairs=versusPairings(week);return '<article class="panel versus-week"><div class="panel-head"><div><span class="eyebrow">WEEK '+week+'</span><h3>'+(week===1?'Opening Pairings':'Path Pairings')+'</h3></div><span class="pill">'+(week===1?'Original order':'Exact '+('W/L '.repeat(week-1)).trim()+' path')+'</span></div><div class="versus-matches">'+(pairs.length?pairs.map((p,mi)=>versusMatchHtml(week,mi,p)).join(''):'<p class="muted">Complete Week '+(week-1)+' results to generate these pairings.</p>')+'</div></article>'}).join('');
 document.querySelectorAll('.versus-result').forEach(sel=>sel.onchange=()=>{const key=sel.dataset.key;if(sel.value)versusData.results[key]=sel.value;else delete versusData.results[key];for(const k of Object.keys(versusData.results)){const w=Number(k.split('-')[0]);if(w>Number(key.split('-')[0]))delete versusData.results[k]}saveVersus();renderVersus()});
 const rows=versusData.teams.map((t,i)=>({i,t,...versusRecord(i)})).sort((a,b)=>b.w-a.w||a.i-b.i);
 renderDashboardVersus();
 renderVersusPrediction();
 renderReminders();
 stand.innerHTML=rows.map((r,rank)=>'<tr><td>'+(rank+1)+'</td><td><strong>'+esc(r.t.name)+'</strong></td><td>'+esc(r.t.power||'—')+'</td><td>'+r.w+'</td><td>'+r.l+'</td><td>'+r.w+'-'+r.l+'</td><td><span class="path-badge">'+esc(r.path||'—')+'</span></td></tr>').join('')
}
function versusMatchHtml(week,mi,p){const a=versusData.teams[p.a],b=versusData.teams[p.b],key=week+'-'+mi,r=versusData.results[key]||'',br=r==='W'?'L':r==='L'?'W':'',winner=r?(r==='W'?a.name:b.name):'—',loser=r?(r==='W'?b.name:a.name):'—';return '<div class="versus-match"><div class="versus-match-head"><strong>Match '+(mi+1)+'</strong><span class="path-badge">'+(p.path||'START')+'</span></div><div class="versus-side"><span>A</span><strong>'+esc(a.name)+'</strong><small>'+esc(a.power||'Power —')+'</small><select class="versus-result" data-key="'+key+'"><option value="">Result</option><option value="W" '+(r==='W'?'selected':'')+'>W</option><option value="L" '+(r==='L'?'selected':'')+'>L</option></select></div><div class="versus-side"><span>B</span><strong>'+esc(b.name)+'</strong><small>'+esc(b.power||'Power —')+'</small><b class="auto-result">'+(br||'—')+'</b></div><div class="versus-outcome"><span>Winner: <strong>'+esc(winner)+'</strong></span><span>Loser: <strong>'+esc(loser)+'</strong></span></div></div>'}

function parseVersusOcr(text){const lines=text.split(/\r?\n/).map(x=>x.trim()).filter(Boolean),rows=[];for(const line of lines){if(rows.length>=16)break;let clean=line.replace(/^\s*#?\d{1,2}[.)\-:]?\s+/,'').trim();if(!clean)continue;const m=clean.match(/^(.*?)(?:\s{2,}|\s+)([\d,.]+\s*[KMBT]?)$/i);if(m)rows.push({name:m[1].trim(),power:m[2].trim()});else rows.push({name:clean,power:''})}return rows}
async function scanVersusPicture(file){const review=document.getElementById('versusPictureReview'),preview=document.getElementById('versusPicturePreview'),status=document.getElementById('versusOcrStatus'),box=document.getElementById('versusOcrText');if(!file||!review||!box)return;review.hidden=false;const reader=new FileReader();reader.onload=()=>preview.src=reader.result;reader.readAsDataURL(file);if(!window.Tesseract){status.textContent='Picture reader did not load. Refresh and try again.';return}status.textContent='Reading picture… 0%';box.value='';try{const result=await Tesseract.recognize(file,'eng',{logger:m=>{if(m.status==='recognizing text')status.textContent='Reading picture… '+Math.round((m.progress||0)*100)+'%'}});box.value=result.data.text.trim();status.textContent='Scan complete. Review the text, then select Apply detected teams.'}catch(e){status.textContent='Could not read this picture: '+e.message}}
function applyVersusOcr(){const box=document.getElementById('versusOcrText'),status=document.getElementById('versusOcrStatus'),rows=parseVersusOcr(box?.value||'');if(!rows.length){if(status)status.textContent='No alliance rows detected. Edit the text and try again.';return}rows.slice(0,16).forEach((r,i)=>{versusData.teams[i]={name:r.name||versusData.teams[i].name,power:r.power||'',nationality:versusData.teams[i].nationality||''}});saveVersus();renderVersus();document.getElementById('versusPictureReview').hidden=true}
function cancelVersusOcr(){document.getElementById('versusPictureReview').hidden=true;document.getElementById('versusPictureInput').value=''}


let versusHistory=[];
function versusComplete(){return Object.keys(versusData.results).filter(k=>versusData.results[k]==='W'||versusData.results[k]==='L').length===32}
function versusSnapshot(){return{version:1,teams:versusData.teams.map((t,i)=>({...t,original_order:i+1,record:versusRecord(i),weeks:Array.from({length:4},(_,wi)=>{const week=wi+1,pair=versusPairings(week).find(p=>p.a===i||p.b===i),opp=pair?(pair.a===i?pair.b:pair.a):null;return{week,opponent:opp===null?null:versusData.teams[opp].name,result:resultFor(i,week)}})})),results:{...versusData.results}}}
async function loadVersusHistory(){if(!cloudReady)return;try{versusHistory=await api('/rest/v1/versus_tournament_history?select=id,completed_at,tournament_data&order=completed_at.desc');renderVersusHistory()}catch(e){console.warn('Versus history load failed',e)}}
function renderVersusHistory(){const root=document.getElementById('versusHistory'),count=document.getElementById('versusHistoryCount');if(!root)return;if(count)count.textContent=versusHistory.length+' archived';root.innerHTML=versusHistory.length?versusHistory.map((h,hi)=>{const teams=h.tournament_data?.teams||[],date=new Date(h.completed_at).toLocaleDateString();return '<details class="versus-history-item"><summary><strong>Tournament '+(versusHistory.length-hi)+'</strong><span>'+esc(date)+' · '+teams.length+' alliances</span></summary><div class="monthly-rotation"><table class="rotation-table"><thead><tr><th>#</th><th>Alliance</th><th>Power</th><th>Nationality</th><th>Record</th><th>Path</th></tr></thead><tbody>'+teams.slice().sort((a,b)=>(b.record?.w||0)-(a.record?.w||0)||(a.original_order||0)-(b.original_order||0)).map(t=>'<tr><td>'+esc(t.original_order)+'</td><td><strong>'+esc(t.name)+'</strong></td><td>'+esc(t.power||'—')+'</td><td>'+esc(t.nationality||'—')+'</td><td>'+esc((t.record?.w||0)+'-'+(t.record?.l||0))+'</td><td><span class="path-badge">'+esc(t.record?.path||'—')+'</span></td></tr>').join('')+'</tbody></table></div></details>'}).join(''):'<p class="muted">No completed tournaments archived yet.</p>'}
async function archiveVersus(){if(!versusComplete())return alert('Complete all 32 matches across Weeks 1–4 before archiving this tournament.');if(!cloudReady)return alert('Connect to the shared cloud before archiving.');if(!confirm('Are you sure you want to archive this tournament? The full 4-week results will be saved to Tournament History.'))return;try{await api('/rest/v1/versus_tournament_history',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({tournament_data:versusSnapshot()})});await loadVersusHistory();alert('Tournament archived. You can now reset the tournament to start the next one.')}catch(e){alert('Could not archive tournament: '+e.message)}}

async function undoLatestVersusArchive(){if(!cloudReady)return alert('Connect to the shared cloud first.');if(!versusHistory.length)return alert('There is no archived tournament to undo.');const latest=versusHistory[0];if(!confirm('Are you sure you want to undo the latest archive? This will permanently remove that tournament from Tournament History.'))return;try{await api('/rest/v1/versus_tournament_history?id=eq.'+encodeURIComponent(latest.id),{method:'DELETE',headers:{Prefer:'return=minimal'}});await loadVersusHistory();alert('Latest tournament archive removed.')}catch(e){alert('Could not undo latest archive: '+e.message)}}
function resetVersus(){if(!confirm('Reset all Versus Duel teams, power values, and results?'))return;versusData=defaultVersus();saveVersus();renderVersus()}

const titles={dashboard:'Alliance Dashboard','season-war':'Season War',members:'Members','todays-schedule':'Today’s Schedule',vs:'Versus Duel','desert-storm':'Desert Storm','canyon-storm':'Canyon Storm',transfer:'Transfer Planning',train:'Train',settings:'Settings'};
function showPage(id){pages.forEach(p=>p.classList.toggle('active',p.id===id));navItems.forEach(n=>n.classList.toggle('active',n.dataset.page===id));title.textContent=titles[id]||id;sidebar.classList.remove('open')}
navItems.forEach(n=>n.onclick=()=>showPage(n.dataset.page));document.getElementById('menuBtn').onclick=()=>sidebar.classList.toggle('open');
const STORAGE_KEY='unbeerable_members_v14';let members=loadMembers(),editingIndex=null,importRows=[],workbook=null;
function memberObj(x){return typeof x==='string'?{name:x,power:'',t1:'',type:''}:{name:String(x?.name||''),power:String(x?.power||''),t1:String(x?.t1||''),type:String(x?.type||'')}}
function loadMembers(){try{const x=JSON.parse(localStorage.getItem(STORAGE_KEY)||localStorage.getItem('unbeerable_members_v13')||'[]');return Array.isArray(x)?x.filter(Boolean).map(memberObj):[]}catch(e){return[]}}
function saveLocal(){localStorage.setItem(STORAGE_KEY,JSON.stringify(members))}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function parseTHP(v){const raw=String(v??'').trim();if(!raw)return 0;const s=raw.replace(/[\s,]/g,'').replace(/[^0-9.+-]/g,''),n=Number(s);if(!Number.isFinite(n))return 0;return n<1000000?n*1000000:n}
function compactTHP(n){if(n>=1e9)return (n/1e9).toFixed(n<1e10?3:2).replace(/0+$/,'').replace(/\.$/,'')+'B';if(n>=1e6)return (n/1e6).toFixed(n>=1e8?1:2).replace(/\.0+$|(?<=\.[0-9])0$/,'')+'M';if(n>=1e3)return (n/1e3).toFixed(1).replace(/\.0$/,'')+'K';return Math.round(n).toLocaleString()}
function updateTroopTypeCounts(){
 const counts={tank:0,air:0,missile:0,unspecified:0};
 members.forEach(m=>{const t=String(m.type||'').trim().toLowerCase();if(t.includes('tank'))counts.tank++;else if(t.includes('air'))counts.air++;else if(t.includes('missile'))counts.missile++;else counts.unspecified++});
 const ids={dashboardTankCount:counts.tank,dashboardAirCount:counts.air,dashboardMissileCount:counts.missile,dashboardUnspecifiedCount:counts.unspecified};
 Object.entries(ids).forEach(([id,v])=>{const e=document.getElementById(id);if(e)e.textContent=v});
 const known=document.getElementById('troopTypeKnown');if(known)known.textContent=(counts.tank+counts.air+counts.missile)+' classified';
}
function updateCount(){updateTroopTypeCounts();const n=members.length,total=members.reduce((sum,m)=>sum+parseTHP(m.power),0);document.getElementById('dashboardMemberCount').textContent=n+'/100';document.getElementById('dashboardMemberSlots').textContent=Math.max(0,100-n)+' open position'+(100-n===1?'':'s');const p=document.getElementById('dashboardTotalPower'),s=document.getElementById('dashboardTotalPowerSource');if(p)p.textContent=compactTHP(total);if(s)s.textContent=total?'Combined member THP':'No THP data'}
function renderMembers(){members=members.map(memberObj).filter(m=>m.name);const q=(document.getElementById('memberSearch').value||'').trim().toLowerCase();const rows=members.map((member,index)=>({member,index})).filter(x=>[x.member.name,x.member.power,x.member.t1,x.member.type].some(v=>String(v).toLowerCase().includes(q)));document.querySelector('#memberTable tbody').innerHTML=rows.map(x=>`<tr><td><strong>${esc(x.member.name)}</strong></td><td>${esc(x.member.power||'—')}</td><td>${esc(x.member.t1||'—')}</td><td>${esc(x.member.type||'—')}</td><td class="row-actions"><button class="mini-btn edit-member" data-index="${x.index}">Edit</button><button class="mini-btn danger delete-member" data-index="${x.index}">Delete</button></td></tr>`).join('');document.getElementById('memberCount').textContent=members.length+' member'+(members.length===1?'':'s');document.getElementById('visibleMemberCount').textContent=rows.length+' shown';document.getElementById('memberEmptyState').hidden=rows.length!==0;updateCount();document.querySelectorAll('.edit-member').forEach(b=>b.onclick=()=>openMember(Number(b.dataset.index)));document.querySelectorAll('.delete-member').forEach(b=>b.onclick=async()=>{const i=Number(b.dataset.index);if(confirm('Delete '+members[i].name+' from the roster?')){members.splice(i,1);saveLocal();renderMembers();await replaceCloudRoster()}})}
function openMember(i=null){editingIndex=i;document.getElementById('memberModalTitle').textContent=i===null?'Add member':'Edit member';const m=i===null?memberObj({}):members[i];document.getElementById('memberNameInput').value=m.name;document.getElementById('memberPowerInput').value=m.power;document.getElementById('memberT1Input').value=m.t1;document.getElementById('memberTypeInput').value=m.type;document.getElementById('memberModal').hidden=false}
function closeMember(){document.getElementById('memberModal').hidden=true;editingIndex=null}
document.getElementById('addMemberBtn').onclick=()=>openMember();document.getElementById('closeMemberModal').onclick=closeMember;document.getElementById('cancelMemberBtn').onclick=closeMember;
document.getElementById('saveMemberBtn').onclick=async()=>{const m={name:document.getElementById('memberNameInput').value.trim(),power:document.getElementById('memberPowerInput').value.trim(),t1:document.getElementById('memberT1Input').value.trim(),type:document.getElementById('memberTypeInput').value.trim()};if(!m.name)return alert('Enter a member name.');if(members.some((n,i)=>i!==editingIndex&&n.name.toLowerCase()===m.name.toLowerCase()))return alert('That member is already in the roster.');if(editingIndex===null)members.push(m);else members[editingIndex]=m;saveLocal();renderMembers();closeMember();await replaceCloudRoster()};
document.getElementById('memberSearch').oninput=renderMembers;document.getElementById('clearMemberSearch').onclick=()=>{document.getElementById('memberSearch').value='';renderMembers()};
function parseCSV(text){const rows=[];let row=[],cell='',quote=false;for(let i=0;i<text.length;i++){const c=text[i],n=text[i+1];if(c==='"'&&quote&&n==='"'){cell+='"';i++}else if(c==='"')quote=!quote;else if(c===','&&!quote){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&n==='\n')i++;row.push(cell);if(row.some(v=>String(v).trim()))rows.push(row);row=[];cell=''}else cell+=c}row.push(cell);if(row.some(v=>String(v).trim()))rows.push(row);return rows}
const HEADERS=['alliance member','member name','member','player name','player','name','username'];function norm(v){return String(v??'').trim().toLowerCase().replace(/[^a-z0-9]+/g,' ')}
function prepareImport(rows,file){let h=null;for(let r=0;r<Math.min(rows.length,20)&&!h;r++){const z=rows[r].map(norm),i=z.findIndex(c=>HEADERS.includes(c));if(i>=0)h={r,name:i,power:z.findIndex(c=>c==='thp'||c==='power'),t1:z.findIndex(c=>c==='t1'),type:z.findIndex(c=>c==='type')}}if(!h)return alert('Could not find a member-name column.');const map=new Map();for(const r of rows.slice(h.r+1)){const name=String(r[h.name]??'').trim();if(!name)continue;map.set(name.toLowerCase(),{name,power:h.power>=0?String(r[h.power]??'').trim():'',t1:h.t1>=0?String(r[h.t1]??'').trim():'',type:h.type>=0?String(r[h.type]??'').trim():''})}importRows=[...map.values()];if(!importRows.length)return alert('No members found.');document.getElementById('importSummary').textContent=importRows.length+' members found in '+file+'. THP, T1 and Type will be imported when present.';document.getElementById('importPreview').innerHTML=importRows.map((m,i)=>`<div><span>${i+1}</span><strong>${esc(m.name)}</strong><small>${esc(m.power||'—')} · T1 ${esc(m.t1||'—')} · ${esc(m.type||'—')}</small></div>`).join('');document.getElementById('importModal').hidden=false}
const fileInput=document.getElementById('memberFileInput');document.getElementById('importMembersBtn').onclick=()=>fileInput.click();fileInput.onchange=async e=>{const f=e.target.files?.[0];if(!f)return;try{const buf=await f.arrayBuffer(),u=new Uint8Array(buf);if(u[0]===0x50&&u[1]===0x4b||u[0]===0xd0&&u[1]===0xcf){if(typeof XLSX==='undefined')throw Error('Excel reader unavailable');workbook=XLSX.read(buf,{type:'array'});let s=workbook.SheetNames[0],sheetRows=null;for(const sn of workbook.SheetNames){const rr=XLSX.utils.sheet_to_json(workbook.Sheets[sn],{header:1,defval:'',raw:false});if(rr.slice(0,20).some(row=>row.map(norm).some(c=>HEADERS.includes(c)))){s=sn;sheetRows=rr;break}}prepareImport(sheetRows||XLSX.utils.sheet_to_json(workbook.Sheets[s],{header:1,defval:'',raw:false}),f.name)}else prepareImport(parseCSV(new TextDecoder().decode(buf)),f.name)}catch(err){alert('Could not read file: '+err.message)}e.target.value=''};
function closeImport(){document.getElementById('importModal').hidden=true;importRows=[]}document.getElementById('closeImportModal').onclick=closeImport;document.getElementById('cancelImportBtn').onclick=closeImport;document.getElementById('replaceRosterBtn').onclick=async()=>{if(!importRows.length)return;if(confirm('Replace roster with '+importRows.length+' imported names?')){members=importRows.map(memberObj);saveLocal();renderMembers();closeImport();await replaceCloudRoster()}};
