let trainTab='conductor',trainState={conductor:{next_index:0,cycle:1},vip:{next_index:0,cycle:1}},trainHistory=[];
const DAYS=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
function allianceNow(){const n=new Date();return new Date(n.getUTCFullYear(),n.getUTCMonth(),n.getUTCDate(),12)}
function mondayOf(offset=0){const d=allianceNow(),day=d.getDay()||7;d.setDate(d.getDate()-day+1+offset*7);return d}
function isoDate(d){return d.toISOString().slice(0,10)}
function currentWeekStart(){return isoDate(mondayOf(0))}
function comingWeekStart(){return isoDate(mondayOf(1))}
function fallbackCurrentTrainRows(){const week=currentWeekStart(),start=68;return DAYS.flatMap((day,i)=>[{week_start:week,day_index:i,role:'conductor',member_name:TRAIN_CONDUCTORS[start+i],cycle:1,fallback:true},{week_start:week,day_index:i,role:'vip',member_name:TRAIN_VIPS[start+i],cycle:1,fallback:true}])}
function currentTrainRows(){const week=currentWeekStart(),saved=trainHistory.filter(x=>x.week_start===week);return saved.length?saved:fallbackCurrentTrainRows()}
function eligibleQueue(role){const source=role==='conductor'?TRAIN_CONDUCTORS:TRAIN_VIPS,set=new Set(members.map(x=>x.name.toLocaleLowerCase()));return source.filter(n=>set.has(n.toLocaleLowerCase()))}
function formatWeek(s){if(!s)return '—';const d=new Date(s+'T12:00:00'),e=new Date(d);e.setDate(e.getDate()+6);return d.toLocaleDateString(undefined,{month:'short',day:'numeric'})+' – '+e.toLocaleDateString(undefined,{month:'short',day:'numeric'})}
async function loadTrainData(){if(!cloudReady)return;try{const [st,hi]=await Promise.all([api('/rest/v1/train_rotation_state?select=role,next_index,cycle'),api('/rest/v1/train_rotation_history?select=week_start,day_index,role,member_name,cycle&order=week_start.desc,day_index.asc')]);(st||[]).forEach(x=>trainState[x.role]={next_index:x.next_index,cycle:x.cycle});trainHistory=hi||[];renderTrain()}catch(e){console.warn('Train load failed',e)}}
function trainEmailMessage(){const week=comingWeekStart(),rows=trainHistory.filter(x=>x.week_start===week);if(!rows.length)return '';const lines=DAYS.map((day,i)=>{const c=rows.find(x=>x.day_index===i&&x.role==='conductor'),v=rows.find(x=>x.day_index===i&&x.role==='vip');return day+' — Driver: '+(c?.member_name||'—')+' | VIP: '+(v?.member_name||'—')});return '# Train rotation for next week\n\nDear all,\n\nThank you for your participation this week 🏆\n\nNext week’s train drivers and vips are assigned according to the list (which can be found on discord). 🚂✨\n\n📅 Train rotation:\n'+lines.join('\n')+'\n\nGeneral instructions:\n⏰ The train starts daily around 17:00 CEST.\n🚂 Drivers have 4h to turn the train golden & choose the VIP.\n⭐ VIPs have 1h to accept after nomination.\n🎁 Please include at least one deco chest / deco components in the train.\n✉️ If your day/time doesn’t work or if you have questions, contact me.\n⚠️ Drivers & VIPs are responsible for being available on their assigned day, so please check your schedule carefully.\n\n🔥 The train drivers and vips will be assigned according to the list (which can be found on discord).\n\nHave a great week! 🌟🍻'}
function renderTrainEmail(){const box=document.getElementById('trainEmailText'),btn=document.getElementById('copyTrainEmailBtn');if(!box)return;const msg=trainEmailMessage();box.value=msg;box.placeholder=msg?'':'Generate the coming week to create the email.';if(btn)btn.disabled=!msg}
async function copyTrainEmail(){const text=trainEmailMessage(),status=document.getElementById('trainCopyStatus');if(!text)return;try{await navigator.clipboard.writeText(text);if(status)status.textContent='Copied to clipboard.'}catch{const box=document.getElementById('trainEmailText');box.focus();box.select();document.execCommand('copy');if(status)status.textContent='Copied to clipboard.'}setTimeout(()=>{if(status)status.textContent=''},2500)}
function renderDashboardTrain(){const el=document.getElementById('dashboardTrainSchedule'),head=document.getElementById('dashboardTrainWeek');if(!el||!head)return;const week=currentWeekStart(),rows=currentTrainRows(),saved=trainHistory.some(x=>x.week_start===week);head.textContent='Current week · '+formatWeek(week)+(saved?'':' · temporary #69–75');el.innerHTML=DAYS.map((day,i)=>{const c=rows.find(x=>x.day_index===i&&x.role==='conductor'),v=rows.find(x=>x.day_index===i&&x.role==='vip');return '<div class="dashboard-train-day"><span>'+day+'</span><div><small>CONDUCTOR</small><strong>'+esc(c?.member_name||'—')+'</strong></div><div><small>VIP</small><strong>'+esc(v?.member_name||'—')+'</strong></div></div>'}).join('')}
function renderTrain(){renderDashboardTrain();renderTrainEmail();const role=trainTab,q=eligibleQueue(role),st=trainState[role]||{next_index:0,cycle:1},week=comingWeekStart(),current=trainHistory.filter(x=>x.week_start===week&&x.role===role);document.getElementById('trainWeekLabel').textContent=formatWeek(week);['conductor','vip'].forEach(r=>{const qq=eligibleQueue(r),ss=trainState[r]||{next_index:0,cycle:1};document.getElementById(r+'Progress').textContent=Math.min(ss.next_index,qq.length)+'/'+qq.length;document.getElementById(r+'Cycle').textContent='Cycle '+ss.cycle});document.getElementById('trainRoleTitle').textContent=(role==='vip'?'VIP':'Conductor')+' schedule';document.getElementById('trainQueueTitle').textContent=(role==='vip'?'VIP':'Conductor')+' list';document.getElementById('trainEligibleCount').textContent=q.length+' eligible';document.getElementById('trainSchedule').innerHTML=DAYS.map((day,i)=>{const x=current.find(v=>v.day_index===i);return '<div class="train-day"><span>'+day+'</span><strong>'+(x?esc(x.member_name):'Not generated')+'</strong><small>'+(x?'Cycle '+x.cycle:'')+'</small></div>'}).join('');document.getElementById('trainQueue').innerHTML=q.length?q.map((n,i)=>'<div class="train-person '+(i<st.next_index?'used ':'')+(i===st.next_index?'next':'')+'"><span class="num">'+(i+1)+'</span><strong>'+esc(n)+'</strong></div>').join(''):'<div class="train-empty">No names from this rotation list are currently in the alliance member roster.</div>';const weeks=[...new Set(trainHistory.map(x=>x.week_start))].sort().reverse();document.getElementById('trainHistory').innerHTML=weeks.length?weeks.map(w=>{const rows=trainHistory.filter(x=>x.week_start===w);return '<div class="train-history-week"><div class="train-history-head">'+formatWeek(w)+'</div><div class="train-history-grid">'+DAYS.map((d,i)=>{const cc=rows.find(x=>x.day_index===i&&x.role==='conductor'),vv=rows.find(x=>x.day_index===i&&x.role==='vip');return '<div class="train-history-cell"><span>'+d+'</span><div>C: '+esc(cc?.member_name||'—')+'</div><div>VIP: '+esc(vv?.member_name||'—')+'</div></div>'}).join('')+'</div></div>'}).join(''):'<div class="train-empty">No previous train rotations yet.</div>'}
async function generateRole(role,week,startNumber=null){const existing=trainHistory.filter(x=>x.week_start===week&&x.role===role);if(existing.length)return;const q=eligibleQueue(role);if(!q.length)throw Error('No eligible '+role+' members are in the alliance roster.');let st={...(trainState[role]||{next_index:0,cycle:1})},rows=[];if(startNumber!==null){if(!Number.isInteger(startNumber)||startNumber<1||startNumber>q.length)throw Error('Start # for '+role+' must be between 1 and '+q.length+'.');st.next_index=startNumber-1;}for(let day=0;day<7;day++){if(st.next_index>=q.length){st.next_index=0;st.cycle++}rows.push({week_start:week,day_index:day,role,member_name:q[st.next_index],cycle:st.cycle});st.next_index++}await api('/rest/v1/train_rotation_history',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify(rows)});await api('/rest/v1/train_rotation_state?role=eq.'+role,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({next_index:st.next_index,cycle:st.cycle,updated_at:new Date().toISOString()})})}
async function undoTrainWeek(){if(!cloudReady)return alert('Connect to the shared cloud first.');const week=comingWeekStart(),rows=trainHistory.filter(x=>x.week_start===week);if(!rows.length)return alert('There is no coming Train week to undo.');if(!confirm('Undo the coming week? This removes all 7 Conductor and 7 VIP assignments from history so you can generate it again.'))return;try{for(const role of ['conductor','vip']){const roleRows=rows.filter(x=>x.role===role).sort((a,b)=>a.day_index-b.day_index),q=eligibleQueue(role);if(roleRows.length){const first=roleRows[0],idx=q.findIndex(n=>n.toLocaleLowerCase()===first.member_name.toLocaleLowerCase());if(idx>=0){await api('/rest/v1/train_rotation_state?role=eq.'+role,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({next_index:idx,cycle:first.cycle,updated_at:new Date().toISOString()})})}}}await api('/rest/v1/train_rotation_history?week_start=eq.'+week,{method:'DELETE',headers:{Prefer:'return=minimal'}});document.getElementById('trainStartNumber').value='';await loadTrainData()}catch(e){alert('Could not undo Train week: '+e.message);await loadTrainData()}}
