const CANYON_STORM_KEY='unbeerable_canyon_storm_v1';let canyonStormTeam='a',canyonStormData=normalizeDesertStorm(null),canyonSaveTimer=null,canyonPictureMatches=[],canyonPictureTarget='a',canyonPictureStaged=null;
function canyonSlot(kind,i){
 const name=canyonStormData[canyonStormTeam][kind][i]||'',used=new Set([...canyonStormData.a.starters,...canyonStormData.a.subs,...canyonStormData.b.starters,...canyonStormData.b.subs].filter(Boolean));
 const opts=members.slice().sort((a,b)=>a.name.localeCompare(b.name)).map(m=>'<option value="'+esc(m.name)+'" '+(m.name===name?'selected':'')+' '+(used.has(m.name)&&m.name!==name?'disabled':'')+'>'+esc(m.name)+'</option>').join('');
 const m=members.find(x=>x.name===name),thp=m?.power||'—',meta=m?[m.t1&&'T1 '+m.t1,m.type].filter(Boolean).join(' · '):'';
 return '<div class="desert-slot"><span>#'+(i+1)+'</span><div class="desert-slot-member"><select data-cs-kind="'+kind+'" data-cs-index="'+i+'"><option value="">— Empty slot —</option>'+opts+'</select>'+(meta?'<small>'+esc(meta)+'</small>':'')+'</div><div class="desert-slot-thp"><small>THP</small><strong>'+esc(thp)+'</strong></div></div>'
}
function renderCanyonStorm(){const label=canyonStormTeam==='a'?'Team A':'Team B',d=canyonStormData[canyonStormTeam],se=document.getElementById('csStarters'),su=document.getElementById('csSubs');if(!se||!su)return;document.querySelectorAll('[data-cs-team]').forEach(b=>b.classList.toggle('active',b.dataset.csTeam===canyonStormTeam));se.innerHTML=d.starters.map((_,i)=>canyonSlot('starters',i)).join('');su.innerHTML=d.subs.map((_,i)=>canyonSlot('subs',i)).join('');const sc=d.starters.filter(Boolean).length,uc=d.subs.filter(Boolean).length;document.getElementById('csPictureBtn').textContent='Import '+label+' from picture';document.getElementById('csTeamLabel').textContent=label;document.getElementById('csTeamFilled').textContent=(sc+uc)+'/30';document.getElementById('csStarterCount').textContent=sc+'/20';document.getElementById('csSubCount').textContent=uc+'/10';document.getElementById('csStartersTitle').textContent=label+' · 20 Starters';document.getElementById('csSubsTitle').textContent=label+' · 10 Subs';document.querySelectorAll('[data-cs-kind]').forEach(sel=>sel.onchange=()=>{canyonStormData[canyonStormTeam][sel.dataset.csKind][Number(sel.dataset.csIndex)]=sel.value;renderCanyonStorm();saveCanyonStorm()})}
async function loadCanyonStorm(){try{const rows=await api('/rest/v1/canyon_storm_roster?slot=eq.current&select=roster_data&limit=1');canyonStormData=normalizeDesertStorm(rows?.[0]?.roster_data);document.getElementById('canyonStormSaveStatus').textContent='Shared roster loaded'}catch(e){const local=localStorage.getItem(CANYON_STORM_KEY);if(local)try{canyonStormData=normalizeDesertStorm(JSON.parse(local))}catch{}document.getElementById('canyonStormSaveStatus').textContent='Local fallback'}renderCanyonStorm()}
function saveCanyonStorm(){localStorage.setItem(CANYON_STORM_KEY,JSON.stringify(canyonStormData));const st=document.getElementById('canyonStormSaveStatus');if(st)st.textContent='Saving…';clearTimeout(canyonSaveTimer);canyonSaveTimer=setTimeout(async()=>{try{await api('/rest/v1/canyon_storm_roster?slot=eq.current',{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({roster_data:canyonStormData,updated_at:new Date().toISOString()})});if(st)st.textContent='Saved to shared roster'}catch(e){if(st)st.textContent='Saved locally · cloud error'}},350)}
function matchCanyonPictureNames(){const raw=document.getElementById('csPictureNames')?.value||'',lines=raw.split(/\n+/).map(x=>x.trim()).filter(Boolean),roster=[...members].sort((a,b)=>b.name.length-a.name.length),found=[];for(let i=0;i<lines.length;i++){const line=lines[i],norm=normalizeDsText(line);let hit=roster.find(m=>norm.includes(normalizeDsText(m.name)));if(!hit)continue;if(found.some(x=>x.name===hit.name))continue;found.push({name:hit.name,thp:extractDsThp(line)||extractDsThp(lines[i+1]||'')})}canyonPictureMatches=found.slice(0,30);const root=document.getElementById('csPictureMatches');root.innerHTML=canyonPictureMatches.length?canyonPictureMatches.map((x,i)=>'<div class="ds-picture-match"><span>'+(i+1)+'. <strong>'+esc(x.name)+'</strong></span><label>THP <input data-cs-thp-index="'+i+'" value="'+esc(x.thp)+'" placeholder="e.g. 172M"></label></div>').join(''):'<div class="train-empty">No roster names matched yet. Correct the OCR text and re-scan.</div>';root.querySelectorAll('[data-cs-thp-index]').forEach(inp=>inp.oninput=()=>{canyonPictureMatches[Number(inp.dataset.csThpIndex)].thp=inp.value.trim();document.getElementById('csApplyPictureNames').disabled=!canyonPictureMatches.some(x=>x.name&&x.thp)});document.getElementById('csApplyPictureNames').disabled=!canyonPictureMatches.some(x=>x.name&&x.thp);document.getElementById('csPictureStatus').textContent=canyonPictureMatches.length?'Matched '+canyonPictureMatches.length+' roster member(s). Review THP before staging.':'No roster matches found.'}
async function scanCanyonPicture(file){const status=document.getElementById('csPictureStatus');if(!window.Tesseract){status.textContent='OCR reader did not load. You can paste/correct OCR text manually.';return}try{status.textContent='Scanning picture…';const result=await Tesseract.recognize(file,'eng',{logger:m=>{if(m.status==='recognizing text')status.textContent='Scanning picture… '+Math.round((m.progress||0)*100)+'%'}});document.getElementById('csPictureNames').value=result?.data?.text||'';matchCanyonPictureNames()}catch(e){status.textContent='Could not scan picture: '+e.message}}
async function saveCanyonThpObservations(rows){if(!rows.length)return;await api('/rest/v1/canyon_storm_thp_observations?on_conflict=event_date,member_name',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify(rows)})}
function stageCanyonPicture(){const approved=canyonPictureMatches.filter(x=>x.name&&x.thp).slice(0,30),names=[...new Set(approved.map(x=>x.name))],d=canyonStormData[canyonPictureTarget],status=document.getElementById('csPictureStatus'),date=document.getElementById('csPictureEventDate')?.value||upcomingFridayIso();if(!approved.length)return;d.starters=Array(20).fill('');d.subs=Array(10).fill('');names.slice(0,20).forEach((n,i)=>d.starters[i]=n);names.slice(20,30).forEach((n,i)=>d.subs[i]=n);canyonPictureStaged={rows:approved.map((x,i)=>({event_date:date,team:canyonPictureTarget.toUpperCase(),role:i<20?'starter':'substitute',slot_number:i<20?i+1:i-19,member_name:x.name,thp:x.thp,sync_status:'pending'}))};canyonStormTeam=canyonPictureTarget;renderCanyonStorm();saveCanyonStorm();document.getElementById('csSyncPictureData').disabled=false;const b=document.getElementById('csSyncMainBtn');b.disabled=false;b.textContent='SYNC THP DATA · '+approved.length;status.textContent='Staged '+approved.length+' reviewed THP values. Make final edits above, then press SYNC.'}
async function syncCanyonPicture(){const status=document.getElementById('csPictureStatus'),main=document.getElementById('csSyncMainBtn'),inner=document.getElementById('csSyncPictureData');if(!canyonPictureStaged?.rows?.length)return;canyonPictureStaged.rows.forEach(r=>{const x=canyonPictureMatches.find(m=>m.name===r.member_name);if(x?.thp)r.thp=x.thp.trim()});try{main.disabled=true;inner.disabled=true;main.textContent='SYNCING…';status.textContent='Queuing reviewed Canyon Storm THP…';await saveCanyonThpObservations(canyonPictureStaged.rows);canyonPictureStaged=null;main.textContent='SYNC THP DATA';status.textContent='SYNC confirmed. Canyon Storm THP is queued for the automation workflow.';setTimeout(()=>document.getElementById('csPictureReview').hidden=true,900)}catch(e){main.disabled=false;inner.disabled=false;main.textContent='SYNC THP DATA · RETRY';status.textContent='SYNC could not be queued: '+e.message}}
document.querySelectorAll('[data-cs-team]').forEach(b=>b.addEventListener('click',()=>{canyonStormTeam=b.dataset.csTeam;renderCanyonStorm()}));
document.getElementById('csPictureBtn')?.addEventListener('click',()=>{canyonPictureTarget=canyonStormTeam;document.getElementById('csPictureInput').click()});
document.getElementById('csPictureInput')?.addEventListener('change',e=>{const f=e.target.files?.[0];if(!f)return;document.getElementById('csPicturePreview').src=URL.createObjectURL(f);document.getElementById('csPictureTitle').textContent='Review Team '+canyonPictureTarget.toUpperCase()+' members + THP';document.getElementById('csPictureNames').value='';document.getElementById('csPictureMatches').innerHTML='';document.getElementById('csApplyPictureNames').disabled=true;document.getElementById('csSyncPictureData').disabled=true;document.getElementById('csSyncMainBtn').disabled=true;canyonPictureStaged=null;const date=document.getElementById('csPictureEventDate');if(date&&!date.value)date.value=upcomingFridayIso();document.getElementById('csPictureReview').hidden=false;scanCanyonPicture(f);e.target.value=''});
document.getElementById('csMatchPictureNames')?.addEventListener('click',matchCanyonPictureNames);document.getElementById('csApplyPictureNames')?.addEventListener('click',stageCanyonPicture);document.getElementById('csSyncPictureData')?.addEventListener('click',syncCanyonPicture);document.getElementById('csSyncMainBtn')?.addEventListener('click',syncCanyonPicture);document.getElementById('csPictureClose')?.addEventListener('click',()=>document.getElementById('csPictureReview').hidden=true);
let dsSkipHistory=[],dsSkipDraft=[],dsSkipMode=false;
function dsPreviousSkipped(){return new Set((dsSkipHistory[0]?.skipped_members||[]).map(n=>String(n).toLocaleLowerCase()))}
function renderDsSkip(){
 const view=document.getElementById('dsSkippedView');if(!view)return;view.hidden=!dsSkipMode;
 const summary=document.querySelector('#desert-storm>.desert-team-summary'),starters=document.querySelector('#dsStarters')?.closest('article'),subs=document.querySelector('#dsSubs')?.closest('article');
 [summary,starters,subs].forEach(e=>{if(e)e.hidden=dsSkipMode});const pic=document.getElementById('dsPictureBtn');if(pic)pic.hidden=dsSkipMode;if(!dsSkipMode)return;
 const blocked=dsPreviousSkipped(),chosen=new Set(dsSkipDraft.map(n=>n.toLocaleLowerCase())),eligible=members.filter(m=>!blocked.has(m.name.toLocaleLowerCase())&&!chosen.has(m.name.toLocaleLowerCase())),sel=document.getElementById('dsSkipMember');
 sel.innerHTML='<option value="">Select eligible member</option>'+eligible.map(m=>'<option value="'+esc(m.name)+'">'+esc(m.name)+'</option>').join('');
 document.getElementById('dsSkipCount').textContent=dsSkipDraft.length;document.getElementById('dsLastSkipCount').textContent=blocked.size;document.getElementById('dsEligibleSkipCount').textContent=eligible.length;
 document.getElementById('dsCurrentSkipped').innerHTML=dsSkipDraft.length?dsSkipDraft.map((n,i)=>'<button class="ds-skip-chip" data-remove-skip="'+i+'">'+esc(n)+' ×</button>').join(''):'<div class="train-empty">No members selected yet.</div>';
 document.querySelectorAll('[data-remove-skip]').forEach(b=>b.onclick=()=>{dsSkipDraft.splice(Number(b.dataset.removeSkip),1);renderDsSkip()});
 document.getElementById('dsSkipHistoryCount').textContent=dsSkipHistory.length+' events';document.getElementById('dsSkipHistory').innerHTML=dsSkipHistory.length?dsSkipHistory.map((h,i)=>'<div class="ds-skip-history-item"><div><strong>'+h.event_date+'</strong><span>'+h.skipped_members.length+' skipped</span></div><p>'+h.skipped_members.map(esc).join(' · ')+'</p>'+(i===0?'<small>Blocked from next event</small>':'')+'</div>').join(''):'<div class="train-empty">No skip history saved yet.</div>'
}
async function loadDsSkipHistory(){try{dsSkipHistory=await api('/rest/v1/desert_storm_skip_history?select=event_date,skipped_members&order=event_date.desc&limit=52')||[]}catch(e){console.warn(e)}const d=document.getElementById('dsSkipDate');if(d&&!d.value){const n=new Date(),add=(5-n.getDay()+7)%7;n.setDate(n.getDate()+add);d.value=n.toISOString().slice(0,10)}renderDsSkip()}
async function saveDsSkipEvent(){const date=document.getElementById('dsSkipDate')?.value;if(!date)return;const blocked=dsPreviousSkipped();if(dsSkipDraft.some(n=>blocked.has(n.toLocaleLowerCase())))return;try{await api('/rest/v1/desert_storm_skip_history?on_conflict=event_date',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({event_date:date,skipped_members:dsSkipDraft,updated_at:new Date().toISOString()})});dsSkipDraft=[];await loadDsSkipHistory()}catch(e){console.warn(e)}}
document.getElementById('dsSkippedTab')?.addEventListener('click',()=>{dsSkipMode=true;document.querySelectorAll('[data-ds-team]').forEach(b=>b.classList.remove('active'));document.getElementById('dsSkippedTab').classList.add('active');renderDsSkip()});
document.querySelectorAll('[data-ds-team]').forEach(b=>b.addEventListener('click',()=>{dsSkipMode=false;document.getElementById('dsSkippedTab')?.classList.remove('active');renderDsSkip()}));
document.getElementById('dsAddSkipped')?.addEventListener('click',()=>{const s=document.getElementById('dsSkipMember');if(s?.value){dsSkipDraft.push(s.value);renderDsSkip()}});
document.getElementById('dsSaveSkipped')?.addEventListener('click',saveDsSkipEvent);loadDsSkipHistory();


const TRANSFER_KEY='unbeerable_transfer_planning_v1',TRANSFER_LIMITS_KEY='unbeerable_transfer_limits_v1';let transferLimits={Elite:0,Contributor:3,Pioneer:30,Follower:40};try{const x=JSON.parse(localStorage.getItem(TRANSFER_LIMITS_KEY)||'null');if(x)Object.keys(transferLimits).forEach(k=>{if(Number.isFinite(Number(x[k]))&&Number(x[k])>=0)transferLimits[k]=Math.floor(Number(x[k]))})}catch{}let transferApplicants=[];try{transferApplicants=JSON.parse(localStorage.getItem(TRANSFER_KEY)||'[]');if(!Array.isArray(transferApplicants))transferApplicants=[]}catch{transferApplicants=[]}
function saveTransfer(){localStorage.setItem(TRANSFER_KEY,JSON.stringify(transferApplicants))}function saveTransferLimits(){localStorage.setItem(TRANSFER_LIMITS_KEY,JSON.stringify(transferLimits))}
function renderTransfer(){
 const cap=document.getElementById('transferCapacity'),body=document.getElementById('transferRows');if(!cap||!body)return;
 cap.innerHTML=Object.entries(transferLimits).map(([rank,max])=>{const used=transferApplicants.filter(x=>x.seat===rank).length,pct=max?Math.min(100,used/max*100):0,remain=Math.max(0,max-used);return '<article class="panel transfer-cap-card"><span>'+rank+'</span><div class="transfer-cap-numbers"><strong>'+used+' / </strong><label>Max <input class="transfer-limit-input" type="number" min="0" step="1" value="'+max+'" data-transfer-limit="'+rank+'"></label></div><small>'+(max?Math.round(used/max*100)+'% filled · '+remain+' remaining':used?'No seats configured · '+used+' assigned':'No seats configured')+'</small><div class="transfer-bar"><i style="width:'+pct+'%"></i></div></article>'}).join('');
 document.getElementById('transferApplicantCount').textContent=transferApplicants.length+' applicant'+(transferApplicants.length===1?'':'s');
 body.innerHTML=transferApplicants.length?transferApplicants.map((x,i)=>'<tr><td>'+(i+1)+'</td><td><input data-tf="'+i+'" data-k="server" value="'+esc(x.server||'')+'" placeholder="681"></td><td><input data-tf="'+i+'" data-k="name" value="'+esc(x.name||'')+'" placeholder="Player"></td><td><select data-tf="'+i+'" data-k="seat"><option value="">Select</option>'+Object.keys(transferLimits).map(r=>'<option '+(x.seat===r?'selected':'')+'>'+r+'</option>').join('')+'</select></td><td><input data-tf="'+i+'" data-k="power" type="number" min="0" step="0.1" value="'+esc(x.power||'')+'"></td><td><input data-tf="'+i+'" data-k="alliance" value="'+esc(x.alliance||'')+'"></td><td><input data-tf="'+i+'" data-k="group" value="'+esc(x.group||'')+'"></td><td><input data-tf="'+i+'" data-k="comments" value="'+esc(x.comments||'')+'"></td><td><button class="secondary transfer-remove" data-remove-transfer="'+i+'">×</button></td></tr>').join(''):'<tr><td colspan="9"><div class="train-empty">No transfer applicants yet.</div></td></tr>';
 cap.querySelectorAll('[data-transfer-limit]').forEach(el=>el.onchange=()=>{transferLimits[el.dataset.transferLimit]=Math.max(0,Math.floor(Number(el.value)||0));saveTransferLimits();renderTransfer()});
 body.querySelectorAll('[data-tf]').forEach(el=>el.onchange=()=>{const i=Number(el.dataset.tf);transferApplicants[i][el.dataset.k]=el.value;saveTransfer();renderTransfer()});
 body.querySelectorAll('[data-remove-transfer]').forEach(b=>b.onclick=()=>{transferApplicants.splice(Number(b.dataset.removeTransfer),1);saveTransfer();renderTransfer()});
}
document.getElementById('transferAddBtn')?.addEventListener('click',()=>{transferApplicants.push({server:'',name:'',seat:'',power:'',alliance:'',group:'',comments:''});saveTransfer();renderTransfer()});renderTransfer();
